// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * Features as a list of disclosures: icon and title in the summary, the text when open. Axes: expand (first: the
 * first one is open, none: all closed), media (none, image: a picture beside the list), tone, density.
 */
import { type ReactNode } from "react";
import { Disclosure, Inline, Stack, Summary, Text } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { EmptyState } from "../components/empty-state";
import { MediaFrame } from "../components/media-frame";
import { SectionFrame } from "../components/section-frame";
import { tpl } from "../utils";
import type { Feature } from "./feature-grid.types";

export type FeatureAccordionProps = {
  id: string;
  title: string;
  features: Feature[];
  empty?: string;
  expand?: "first" | "none";
  media?: "none" | "image";
  multiple?: boolean;
  tone?: "default" | "muted";
  density?: "default" | "compact";
  landmarkLabel?: string;
};

export function FeatureAccordion({
  id,
  title,
  features,
  empty = "",
  expand = "first",
  media = "none",
  multiple = false,
  tone = "default",
  density = "default",
  landmarkLabel,
}: FeatureAccordionProps) {
  return (
    <SectionFrame
      id={id}
      title={title}
      tone={tone}
      density={density}
      layout={(((media as string) === "image") ? "split" : "stack")}
      media={{ show: ((media as string) === "image") }}
      landmarkLabel={landmarkLabel}
      aside={(
        <MediaFrame alt={title} ratio="4/3" />
      )}
    >
      {((features?.length ?? 0) === 0) ? (
        <EmptyState icon="layout-grid" title={empty} />
      ) : (
        <Stack gap="0" align="stretch" data-testid="items">
          {(features ?? []).map((f, i) => (
            <Disclosure key={f.id}
              variant="item"
              name={(multiple ? undefined : tpl("{0}-accordion", (id ?? "accordion")))}
              open={(((expand as string) === "first") && (i === 0))}
              data-testid="item"
            >
              <Summary variant="item">
                <Inline className="flex min-w-0 items-center justify-start gap-4">
                  <LucideIcon name={f.icon} size={20} />
                  <Inline className="text-base font-semibold">
                    {f.title}
                  </Inline>
                </Inline>
              </Summary>
              <Text size="sm" className="pb-4 text-muted-foreground">
                {f.text}
              </Text>
            </Disclosure>
          ))}
        </Stack>
      )}
    </SectionFrame>
  );
}
